import React, { useState } from "react";
import { Link } from "react-router-dom";

function NavBar() {
    const [isShow,setIsShow] = useState(false); 
    
  const planets = [
    "Mercury",
    "Venus",
    "Earth",
    "Mars",
    "Jupiter",
    "Saturn",
    "Uranus",
    "Neptune",
  ];

  return (
    <nav className=" text-white  h-12">
      <div className="header justify-between flex">
        {/* header */}
        <Link to="/" className=" text-3xl">
          Solar System
        </Link>
        {/* <div className=" pe-3 m-1 " onClick={()=>{setIsShow(!isShow)}}>
        <img width="30" height="30" src="https://img.icons8.com/ios/50/FFFFFF/menu--v1.png" alt="menu--v1"/>
        </div> */}
        {/* list */}
        <div className="">
          <ul className=" flex p">
            <li>Home</li>
            <li>
            <select name="" id="" className=" bg-transparent">
            {
              planets.map((p)=>{
                return <option className=" bg-transparent" value={p}>{p}</option>
              })
            }

            </select>
            </li>
           
          </ul>
        </div>

      </div>
    </nav>
  );
}

export default NavBar;
